using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckBuzkashi {
[DefaultExecutionOrder(250)]public sealed class BuzCabPresentation:MonoBehaviour {
 public BuzMatch match;public SportsEventCamera[] views;public Transform[] interiors;public SportsCabLook[] look;public LineRenderer eligibleRing;public int Humans{get;private set;}public readonly int[] owners=new int[4];
 public void Layout(){Humans=SportsCameraOptions.Select(match.setup,owners);bool cab=match.option==1&&Humans>0;match.broadcast.view.enabled=!cab;match.cameras=cab?new Camera[Humans]:new[]{match.broadcast.view};for(int v=0;v<4;v++){views[v].view.enabled=cab&&v<Humans;interiors[v].gameObject.SetActive(cab&&v<Humans);if(cab&&v<Humans){views[v].view.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(Humans,v);match.cameras[v]=views[v].view;views[v].cabSteering.Bind(match.trucks[owners[v]]);var visibility=views[v].GetComponent<BowlingCabCamera>();if(visibility!=null)visibility.exterior=match.trucks[owners[v]].visuals.GetComponentsInChildren<Renderer>(true);look[v].ResetLook();}}}
 void LateUpdate(){bool eligible=false;for(int i=0;i<6;i++)if(match.setup.players[i].source!=BowlingSource.AI&&match.CanGrab(i))eligible=true;eligibleRing.enabled=match.Live&&match.Owner<0&&eligible;if(eligibleRing.enabled)eligibleRing.transform.position=match.cargo.position+Vector3.down*.5f;if(match.option!=1||Humans==0)return;int mouseOwner=-1;for(int v=0;v<Humans;v++)if(match.setup.players[owners[v]].source==BowlingSource.Keyboard){mouseOwner=owners[v];break;}for(int v=0;v<Humans;v++){int i=owners[v];var body=match.trucks[i].body;var forward=Vector3.ProjectOnPlane(body.rotation*Vector3.forward,Vector3.up);var basis=forward.sqrMagnitude>.01f?Quaternion.LookRotation(forward):Quaternion.identity;var c=views[v].view;c.transform.position=body.position+Vector3.up*1.05f+basis*Vector3.forward*.1f;c.transform.rotation=basis;interiors[v].SetPositionAndRotation(c.transform.position,basis);c.transform.rotation=look[v].Apply(basis,match.setup.players[i],i,i==mouseOwner,match.Live&&match.Phase==BuzPhase.Playing,SportsLookOptions.Sensitivity,SportsLookOptions.InvertY);}}
 public void Release(){if(look!=null)foreach(var l in look)if(l!=null)l.ReleaseCursor();if(eligibleRing!=null)eligibleRing.enabled=false;}void OnDisable(){Release();}
}}
